pub fn square_nums(nums: &Vec<i32>) -> (/* squared */ Vec<i32>) {
    // Precondition guarantees: for each element x, x*x is in [0, i32::MAX).
    // Still, compute in i64 to avoid any intermediate overflow concerns.
    let mut squared = Vec::with_capacity(nums.len());
    for &x in nums.iter() {
        let y = (x as i64) * (x as i64);
        squared.push(y as i32);
    }
    squared
}

